@@ -21,3 +21,31 @@ describe('the websocket frame validator', () => {
     expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
   });
 });
+
+describe('the list_sessions frame', () => {
+  it('forwards limit and before without a client userId, and refuses a fractional limit or a cursor with no usable time or id', () => {
+    const before = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
+    const refused = [
+      {type: 'list_sessions', limit: 'ten'},
+      {type: 'list_sessions', limit: -1},
+      {type: 'list_sessions', limit: 1.5},
+      {type: 'list_sessions', before: 'not-an-object'},
+      {type: 'list_sessions', before: {updatedAt: before.updatedAt, sessionId: ''}},
+      {type: 'list_sessions', before: {updatedAt: before.updatedAt, sessionId: 'a'.repeat(129)}},
+      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
+      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
+    ];
+
+    expect({
+      bare: validateMessage({type: 'list_sessions'}),
+      paged: validateMessage({type: 'list_sessions', limit: 10, before, userId: 'u2'}),
+      byEpoch: validateMessage({type: 'list_sessions', before: {updatedAt: 0, sessionId: 's1'}}),
+      refused: refused.map(frame => validateMessage(frame).valid),
+    }).toEqual({
+      bare: {valid: true, data: {type: 'list_sessions'}},
+      paged: {valid: true, data: {type: 'list_sessions', limit: 10, before}},
+      byEpoch: {valid: true, data: {type: 'list_sessions', before: {updatedAt: 0, sessionId: 's1'}}},
+      refused: Array(refused.length).fill(false),
+    });
+  });
+});
diff --git a/src/transport/ws/validation.ts b/src/transport/ws/validation.ts
index 6e67a6a..3ba5ff4 100644
--- a/src/transport/ws/validation.ts
+++ b/src/transport/ws/validation.ts
@@ -1,6 +1,7 @@
-import type {IncomingMessage} from '../../types/messages.js';
+import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';

 const MAX_CONTENT_LENGTH = 10000;
+const MAX_SESSION_ID_LENGTH = 128;

 interface ValidationSuccess {
   valid: true;
@@ -30,6 +31,8 @@ export function validateMessage(payload: unknown): ValidationResult {
       return validateUserMessage(message);
     case 'ping':
       return validatePingMessage(message);
+    case 'list_sessions':
+      return validateListSessionsMessage(message);
     default:
       return {valid: false, error: `Unknown message type: ${message.type}`};
   }
@@ -72,3 +75,36 @@ function validatePingMessage(message: Record<string, unknown>): ValidationResult
     },
   };
 }
+
+function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
+  const {limit, before} = message;
+  const data: ListSessionsMessage = {type: 'list_sessions'};
+
+  if (limit !== undefined) {
+    if (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 0) {
+      return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
+    }
+    data.limit = limit;
+  }
+
+  if (before !== undefined) {
+    if (!isCursor(before)) {
+      return {
+        valid: false,
+        error: `list_sessions before must be {updatedAt, sessionId} with a valid time and a 1-${MAX_SESSION_ID_LENGTH} char id`,
+      };
+    }
+    data.before = {updatedAt: before.updatedAt, sessionId: before.sessionId};
+  }
+
+  return {valid: true, data};
+}
+
+function isCursor(value: unknown): value is {updatedAt: string | number; sessionId: string} {
+  if (typeof value !== 'object' || value === null) return false;
+  const {updatedAt, sessionId} = value as Record<string, unknown>;
+  const validId = typeof sessionId === 'string' && sessionId.length >= 1 && sessionId.length <= MAX_SESSION_ID_LENGTH;
+  const validTime =
+    (typeof updatedAt === 'string' || typeof updatedAt === 'number') && Number.isFinite(new Date(updatedAt).getTime());
+  return validId && validTime;
+}
